<!doctype html><html lang="en"><head><meta charset="UTF-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#26384b}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}th{background:#e5f2f6}</style></head><body><h1>Admission Register</h1><p>Printed {{ now()->format('d-m-Y') }} &middot; {{ $students->count() }} admissions</p><table><thead><tr><th>Date</th><th>Admission No</th><th>Name</th><th>Father</th><th>Phone</th><th>Class</th><th>Status</th></tr></thead><tbody>@foreach($students as $student)<tr><td>{{ $student->admission_date->format('d-m-Y') }}</td><td>{{ $student->admission_no }}</td><td>{{ $student->first_name }} {{ $student->last_name }}</td><td>{{ $student->father_name }}</td><td>{{ $student->phone }}</td><td>{{ $options['class_id'][$student->class_id] ?? 'Unassigned' }}</td><td>{{ $student->status }}{{ $student->trashed() ? ' (archived)' : '' }}</td></tr>@endforeach</tbody></table></body></html>
